'use strict';

const db = require('../../database');
const user = require('../../user');
const posts = require('../../posts');
const privileges = require('../../privileges');
const meta = require('../../meta');

module.exports = function (SocketPosts) {
	SocketPosts.getVoters = async function (socket, data) {
		if (!data || !data.pid || !data.cid) {
			throw new Error('[[error:invalid-data]]');
		}
		const showDownvotes = !meta.config['downvote:disabled'];
		const canSeeVotes = meta.config.votesArePublic || await privileges.categories.isAdminOrMod(data.cid, socket.uid);
		if (!canSeeVotes) {
			throw new Error('[[error:no-privileges]]');
		}
		const [upvoteUids, downvoteUids] = await Promise.all([
			db.getSetMembers(`pid:${data.pid}:upvote`),
			showDownvotes ? db.getSetMembers(`pid:${data.pid}:downvote`) : [],
		]);

		const [upvoters, downvoters] = await Promise.all([
			user.getUsersFields(upvoteUids, ['username', 'userslug', 'picture']),
			user.getUsersFields(downvoteUids, ['username', 'userslug', 'picture']),
		]);

		return {
			upvoteCount: upvoters.length,
			downvoteCount: downvoters.length,
			showDownvotes: showDownvotes,
			upvoters: upvoters,
			downvoters: downvoters,
		};
	};

	SocketPosts.getUpvoters = async function (socket, pids) {
		if (!Array.isArray(pids)) {
			throw new Error('[[error:invalid-data]]');
		}
		const cids = await posts.getCidsByPids(pids);
		if (!(await user.isAdministrator(socket.uid))) {
			const allowed = await privileges.categories.isUserAllowedTo('topics:read', cids, socket.uid);
			if (cids.some((cid, index) => !cid || !allowed[index])) {
				throw new Error('[[error:no-privileges]]');
			}
		}
		const data = await posts.getUpvotedUidsByPids(pids);
		if (!data.length) {
			return [];
		}

		const cutoff = 6;
		const visibleUids = data.map(uids => (uids.length >= cutoff ? uids.slice(0, cutoff - 1) : uids));
		const uniqueUids = [...new Set(visibleUids.flat())];
		const usernames = await user.getUsernamesByUids(uniqueUids);
		const uidToUsername = new Map(uniqueUids.map((uid, index) => [uid, usernames[index]]));
		return data.map((uids, index) => ({
			cutoff,
			otherCount: uids.length - visibleUids[index].length,
			usernames: visibleUids[index].map(uid => uidToUsername.get(uid)),
		}));
	};
};
